fn NBU_validator_cut(
    statement: &PoolV1PairForestTerminalStatementV1,
    payment: Result<[u8;216],PoolV1PaymentStatementFormatError>,
    lane: Result<u8,PoolV1PairForestAccountErrorV1>,
    late: Result<(),PoolV1PairLatePublicStatementErrorV1>,
) -> Result<(), PoolV1PairForestTerminalFormatErrorV1> {
    let common = statement.common();
    if common.master_account == [0u8; 32]
        || common.checkpoint_account == [0u8; 32]
        || common.selected_lane_account == [0u8; 32]
    {
        return Err(PoolV1PairForestTerminalFormatErrorV1::NonZeroBinding);
    }
    if usize::from(common.output_lane) >= POOL_V1_PAIR_FOREST_LANE_COUNT {
        return Err(PoolV1PairForestTerminalFormatErrorV1::InvalidOutputLane);
    }
    payment.map_err(PoolV1PairForestTerminalFormatErrorV1::Payment)?;
    let (pool, deployment, anchor_sequence, anchor, nullifier, _) =
        statement_public_common(statement);
    if pool != common.master_account {
        return Err(PoolV1PairForestTerminalFormatErrorV1::MasterBindingMismatch);
    }
    if deployment != common.lane_transition.live_snapshot.deployment_domain {
        return Err(PoolV1PairForestTerminalFormatErrorV1::DeploymentBindingMismatch);
    }
    if common.lane_transition.live_snapshot.pool != common.master_account {
        return Err(PoolV1PairForestTerminalFormatErrorV1::MasterBindingMismatch);
    }
    if anchor_sequence != common.checkpoint_sequence {
        return Err(PoolV1PairForestTerminalFormatErrorV1::CheckpointBindingMismatch);
    }
    if anchor != common.historical_global_anchor {
        return Err(PoolV1PairForestTerminalFormatErrorV1::HistoricalAnchorMismatch);
    }
    let expected_lane = lane
        .map_err(|error| PoolV1PairForestTerminalFormatErrorV1::Account(error))?;
    if expected_lane != common.output_lane {
        return Err(PoolV1PairForestTerminalFormatErrorV1::OutputLaneMismatch);
    }
    late.map_err(PoolV1PairForestTerminalFormatErrorV1::LaneTransition)?;
    Ok(())
}

fn NBU_expected(s:&PoolV1PairForestTerminalStatementV1,pay:Result<[u8;216],PoolV1PaymentStatementFormatError>,lane:Result<u8,PoolV1PairForestAccountErrorV1>,late:Result<(),PoolV1PairLatePublicStatementErrorV1>)->Result<(),PoolV1PairForestTerminalFormatErrorV1>{
 let c=s.common(); let (pool,domain,seq,anchor,_,_)=statement_public_common(s);
 if c.master_account==[0;32]||c.checkpoint_account==[0;32]||c.selected_lane_account==[0;32] {Err(PoolV1PairForestTerminalFormatErrorV1::NonZeroBinding)}
 else if c.output_lane>=8 {Err(PoolV1PairForestTerminalFormatErrorV1::InvalidOutputLane)}
 else {match pay {
  Err(e)=>Err(PoolV1PairForestTerminalFormatErrorV1::Payment(e)),
  Ok(_)=>{
   if pool!=c.master_account {Err(PoolV1PairForestTerminalFormatErrorV1::MasterBindingMismatch)}
   else if domain!=c.lane_transition.live_snapshot.deployment_domain {Err(PoolV1PairForestTerminalFormatErrorV1::DeploymentBindingMismatch)}
   else if c.lane_transition.live_snapshot.pool!=c.master_account {Err(PoolV1PairForestTerminalFormatErrorV1::MasterBindingMismatch)}
   else if seq!=c.checkpoint_sequence {Err(PoolV1PairForestTerminalFormatErrorV1::CheckpointBindingMismatch)}
   else if anchor!=c.historical_global_anchor {Err(PoolV1PairForestTerminalFormatErrorV1::HistoricalAnchorMismatch)}
   else {match lane {
    Err(e)=>Err(PoolV1PairForestTerminalFormatErrorV1::Account(e)),
    Ok(l)=>if l!=c.output_lane {Err(PoolV1PairForestTerminalFormatErrorV1::OutputLaneMismatch)} else {match late {Err(e)=>Err(PoolV1PairForestTerminalFormatErrorV1::LaneTransition(e)),Ok(())=>Ok(())}}
   }}
  }
 }}
}
